export const QUTTY_MCP_SCRIPT =
  '#!/usr/bin/env bash\n# qutty-mcp: the Qutty agent hub\'s MCP server, as a stdio command. It relays MCP\'s JSON-RPC lines\n# to this tile\'s hub socket ($QUTTY_SOCK, set by Qutty in every tile); the socket tells the hub\n# which tile is talking. Outside Qutty it exits at once, so a user-scope registration is harmless\n# in other terminals. Installed to ~/.qutty/bin by Qutty (updated on every start).\n#\n# In the shared Docker sandbox a host socket is out of reach: the tile has $QUTTY_HUB\n# (host.docker.internal:<port>) and $QUTTY_TILE_TOKEN instead, and the token, sent as the first\n# line, tells the hub which tile is talking.\nif [ -n "${QUTTY_SOCK:-}" ] && [ -S "$QUTTY_SOCK" ]; then\n  # BSD/OpenBSD netcat has -U (unix sockets); busybox nc does not, so fall back to socat.\n  if command -v nc >/dev/null 2>&1 && nc -h 2>&1 | grep -q -- \'-U\'; then\n    exec nc -U "$QUTTY_SOCK"\n  fi\n  if command -v socat >/dev/null 2>&1; then\n    exec socat - "UNIX-CONNECT:$QUTTY_SOCK"\n  fi\n  echo "qutty-mcp: needs nc with -U (BSD netcat) or socat" >&2\n  exit 1\nfi\n[ -n "${QUTTY_HUB:-}" ] && [ -n "${QUTTY_TILE_TOKEN:-}" ] || exit 0\nhost="${QUTTY_HUB%:*}"\nport="${QUTTY_HUB##*:}"\n# bash\'s own /dev/tcp first (no nc in most images), else nc.\nif exec 3<>"/dev/tcp/$host/$port"; then\n  printf \'%s\\n\' "$QUTTY_TILE_TOKEN" >&3\n  cat <&3 &\n  reader=$!\n  trap \'kill "$reader" 2>/dev/null\' EXIT HUP INT TERM\n  cat >&3\n  exit 0\nfi 2>/dev/null\nif command -v nc >/dev/null 2>&1; then\n  { printf \'%s\\n\' "$QUTTY_TILE_TOKEN"; exec cat; } | nc "$host" "$port" && exit 0\nfi\necho "qutty-mcp: cannot reach the Qutty hub at $QUTTY_HUB" >&2\nexit 1\n';

