export const QUTTY_HOOK_SCRIPT =
  '#!/usr/bin/env bash\n# qutty-hook [harness]: a Claude Code (or compatible) hook command for the Qutty agent hub. It\n# sends the hook\'s JSON input (stdin) to this tile\'s hub socket ($QUTTY_SOCK) as one line and\n# prints the hub\'s one-line JSON reply (pending messages as context, or a Stop block) as the\n# hook\'s output. Outside Qutty, or when the hub cannot be reached, it prints nothing and exits 0,\n# so the agent carries on as if there were no hook. Installed to ~/.qutty/bin by Qutty.\n#\n# qutty-hook say <text...> [--mood neutral|thinking|attention|success|confused|mad|sad|excited|\n#                sleepy|love|surprised|shocked|wow] [--action id:label]... [--timeout ms] [--wait]\n# makes Loopy, the window\'s companion, say something (the `loopy-say` shape). --wait prints the\n# id of the button pressed (nothing when the bubble was closed). A refused message is reported\n# on stderr with exit code 1.\n#\n# In the shared Docker sandbox the hub is reached over TCP instead ($QUTTY_HUB, host:port), the\n# tile\'s token ($QUTTY_TILE_TOKEN) sent as the first line.\nif [ -n "${QUTTY_SOCK:-}" ] && [ -S "$QUTTY_SOCK" ]; then\n  unset QUTTY_HUB\nelif [ -z "${QUTTY_HUB:-}" ] || [ -z "${QUTTY_TILE_TOKEN:-}" ]; then\n  exit 0\nfi\n\n# The TCP half of ask_hub: bash\'s /dev/tcp, else nc. A refused token\'s reply is dropped.\nask_tcp() {\n  local host="${QUTTY_HUB%:*}" port="${QUTTY_HUB##*:}" reply=""\n  if exec 3<>"/dev/tcp/$host/$port"; then\n    printf \'%s\\n%s\\n\' "$QUTTY_TILE_TOKEN" "$2" >&3\n    IFS= read -r -t "$1" reply <&3\n    exec 3>&-\n  elif command -v nc >/dev/null 2>&1; then\n    reply="$(printf \'%s\\n%s\\n\' "$QUTTY_TILE_TOKEN" "$2" | nc -w "$1" "$host" "$port" | head -n 1)"\n  fi\n  case "$reply" in \'\' | *\'"jsonrpc"\'*) ;; *) printf \'%s\\n\' "$reply" ;; esac\n} 2>/dev/null\n\n# Send one line to the hub, print the first line back. $1: idle timeout in seconds.\nask_hub() {\n  if [ -n "${QUTTY_HUB:-}" ]; then\n    ask_tcp "$@"\n  elif command -v nc >/dev/null 2>&1 && nc -h 2>&1 | grep -q -- \'-U\'; then\n    printf \'%s\\n\' "$2" | nc -w "$1" -U "$QUTTY_SOCK" 2>/dev/null | head -n 1\n  elif command -v socat >/dev/null 2>&1; then\n    printf \'%s\\n\' "$2" | socat -t "$1" - "UNIX-CONNECT:$QUTTY_SOCK" 2>/dev/null | head -n 1\n  fi\n}\n\n# A JSON string for $1 (control characters other than tab and newline are dropped).\njson_str() {\n  local s\n  s="$(printf \'%s\' "$1" | LC_ALL=C tr -d \'\\000-\\010\\013\\014\\016-\\037\')"\n  s="${s//\\\\/\\\\\\\\}"\n  s="${s//\\"/\\\\\\"}"\n  s="${s//$\'\\t\'/\\\\t}"\n  s="${s//$\'\\n\'/\\\\n}"\n  printf \'"%s"\' "$s"\n}\n\nif [ "${1:-}" = "say" ]; then\n  shift\n  wait_for=10\n  args=""\n  for a in "$@"; do\n    [ "$a" = "--wait" ] && wait_for=130\n    args="${args:+$args,}$(json_str "$a")"\n  done\n  reply="$(ask_hub "$wait_for" "{\\"qutty\\":\\"say\\",\\"args\\":[$args]}")"\n  case "$reply" in\n    *\'"error":\'*)\n      printf \'qutty-hook say: %s\\n\' "$(printf \'%s\' "$reply" | sed -n \'s/.*"error":"\\(.*\\)"}$/\\1/p\')" >&2\n      exit 1 ;;\n    *\'"action":"\'*) printf \'%s\\n\' "$(printf \'%s\' "$reply" | sed -n \'s/.*"action":"\\([^"]*\\)".*/\\1/p\')" ;;\n  esac\n  exit 0\nfi\n\nharness="${1:-}"\ncase "$harness" in *[!A-Za-z0-9._-]*) harness="" ;; esac\n# One JSON object; a raw newline cannot occur inside a JSON string, so dropping them is safe.\ninput="$(tr -d \'\\r\\n\')"\n[ -n "$input" ] || input="null"\nreply="$(ask_hub 10 "{\\"qutty\\":\\"hook\\",\\"harness\\":\\"$harness\\",\\"input\\":$input}")"\ncase "$reply" in "{"*) printf \'%s\\n\' "$reply" ;; esac\nexit 0\n';
